const pptxgen = require("pptxgenjs");

const pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.title = "Cloudflare Radar 2024 Year in Review";
pres.author = "Cloudflare Radar";

// ── Color palette (dark navy, Cloudflare-inspired) ──────────────────────────
const C = {
  navy:      "0A1628",   // slide background
  navyMid:   "0F2244",   // card background
  navyLight: "1A3A6B",   // secondary card
  orange:    "F6821F",   // Cloudflare accent
  ice:       "A8C8F8",   // light blue text / subtext
  white:     "FFFFFF",
  muted:     "7B9EC8",
  teal:      "00B4D8",
  red:       "E63946",
  green:     "2DC653",
  yellow:    "FFD166",
};

const ASSETS = "/app/benchmark/assets";

// ── Helper: slide header bar ─────────────────────────────────────────────────
function addHeader(slide, title, subtitle) {
  // top accent strip
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.06,
    fill: { color: C.orange }, line: { color: C.orange }
  });
  // Title
  slide.addText(title, {
    x: 0.45, y: 0.18, w: 9.1, h: 0.52,
    fontSize: 22, bold: true, color: C.white, fontFace: "Calibri",
    margin: 0
  });
  if (subtitle) {
    slide.addText(subtitle, {
      x: 0.45, y: 0.68, w: 9.1, h: 0.32,
      fontSize: 11, color: C.ice, fontFace: "Calibri", margin: 0
    });
  }
  // Thin separator line
  slide.addShape(pres.shapes.LINE, {
    x: 0.45, y: 0.97, w: 9.1, h: 0,
    line: { color: C.navyLight, width: 1 }
  });
}

// ── Helper: stat callout card ────────────────────────────────────────────────
function addStatCard(slide, x, y, w, h, value, label, accentColor) {
  slide.addShape(pres.shapes.RECTANGLE, {
    x, y, w, h,
    fill: { color: C.navyMid },
    shadow: { type: "outer", color: "000000", blur: 8, offset: 3, angle: 135, opacity: 0.3 }
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x, y, w: 0.06, h,
    fill: { color: accentColor || C.orange }, line: { color: accentColor || C.orange }
  });
  slide.addText(value, {
    x: x + 0.14, y: y + 0.08, w: w - 0.2, h: h * 0.55,
    fontSize: 32, bold: true, color: C.white, fontFace: "Calibri",
    valign: "middle", margin: 0
  });
  slide.addText(label, {
    x: x + 0.14, y: y + h * 0.62, w: w - 0.2, h: h * 0.35,
    fontSize: 10, color: C.ice, fontFace: "Calibri",
    valign: "top", wrap: true, margin: 0
  });
}

// ═══════════════════════════════════════════════════════════════════════════
// SLIDE 1 — TITLE SLIDE
// ═══════════════════════════════════════════════════════════════════════════
{
  const slide = pres.addSlide();
  slide.background = { color: C.navy };

  // Background decorative shapes
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 7.2, y: 0, w: 2.8, h: 5.625,
    fill: { color: C.navyMid }, line: { color: C.navyMid }
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 4.8, w: 10, h: 0.825,
    fill: { color: C.navyMid }, line: { color: C.navyMid }
  });

  // Orange accent top bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 7.1, h: 0.07,
    fill: { color: C.orange }, line: { color: C.orange }
  });

  // Cloudflare label
  slide.addText("CLOUDFLARE RADAR", {
    x: 0.55, y: 0.25, w: 6, h: 0.38,
    fontSize: 13, bold: true, color: C.orange, fontFace: "Calibri",
    charSpacing: 4, margin: 0
  });

  // Main title
  slide.addText("2024 Year in Review", {
    x: 0.55, y: 0.78, w: 6.3, h: 1.4,
    fontSize: 46, bold: true, color: C.white, fontFace: "Calibri",
    margin: 0
  });

  // Subtitle
  slide.addText("Global Internet Traffic · Technology Adoption · Security Threats", {
    x: 0.55, y: 2.22, w: 6.3, h: 0.5,
    fontSize: 13, color: C.ice, fontFace: "Calibri",
    margin: 0
  });

  // Divider line
  slide.addShape(pres.shapes.LINE, {
    x: 0.55, y: 2.82, w: 3.5, h: 0,
    line: { color: C.orange, width: 2 }
  });

  // Description
  slide.addText(
    "A data-driven analysis of Internet patterns observed through Cloudflare's global network during 2024. Covering traffic growth, popular services, technology adoption, connectivity disruptions, and the evolving security landscape.",
    {
      x: 0.55, y: 3.0, w: 6.3, h: 1.4,
      fontSize: 11.5, color: C.muted, fontFace: "Calibri",
      wrap: true, margin: 0
    }
  );

  // Bottom-right meta
  slide.addText("radar.cloudflare.com/year-in-review/2024", {
    x: 0, y: 4.85, w: 9.5, h: 0.38,
    fontSize: 10, color: C.muted, align: "right", fontFace: "Calibri", margin: 0
  });

  // Right panel decoration — small stat previews
  const stats = [
    { v: "17%", l: "Traffic Growth" },
    { v: "225", l: "Disruptions" },
    { v: "6.5%", l: "Traffic Mitigated" },
  ];
  stats.forEach((s, i) => {
    const ty = 0.7 + i * 1.55;
    slide.addText(s.v, {
      x: 7.3, y: ty, w: 2.5, h: 0.8,
      fontSize: 36, bold: true, color: C.orange, fontFace: "Calibri",
      align: "center", margin: 0
    });
    slide.addText(s.l, {
      x: 7.3, y: ty + 0.75, w: 2.5, h: 0.35,
      fontSize: 10, color: C.ice, fontFace: "Calibri",
      align: "center", margin: 0
    });
    if (i < stats.length - 1) {
      slide.addShape(pres.shapes.LINE, {
        x: 7.5, y: ty + 1.2, w: 2.1, h: 0,
        line: { color: C.navyLight, width: 1 }
      });
    }
  });
}

// ═══════════════════════════════════════════════════════════════════════════
// SLIDE 2 — 17% Global Traffic Growth and Starlink's 3.3x Surge
// ═══════════════════════════════════════════════════════════════════════════
{
  const slide = pres.addSlide();
  slide.background = { color: C.navy };
  addHeader(slide,
    "17% Global Traffic Growth and Starlink's 3.3x Surge",
    "Continued upward trend driven by Internet reliance across communication, commerce, entertainment, and connectivity"
  );

  // Left column — stat cards
  addStatCard(slide, 0.35, 1.15, 2.3, 1.15, "17%", "Global Internet traffic growth YoY in 2024", C.orange);
  addStatCard(slide, 0.35, 2.45, 2.3, 1.15, "3.3×", "Starlink traffic surge — satellite connectivity to underserved regions", C.teal);
  addStatCard(slide, 0.35, 3.75, 2.3, 1.05, "41%", "Global traffic from mobile devices in 2024", C.ice);

  // Context note
  slide.addText(
    "Traffic trend starts mid-January to normalize for post-holiday activity. Starlink trend is scaled relative to peak observed request volume.",
    {
      x: 0.35, y: 4.85, w: 2.3, h: 0.55,
      fontSize: 8.5, color: C.muted, fontFace: "Calibri", wrap: true, margin: 0
    }
  );

  // Right column — Starlink image
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 2.9, y: 1.1, w: 6.8, h: 4.25,
    fill: { color: C.navyMid }, line: { color: C.navyLight }
  });
  slide.addImage({
    path: `${ASSETS}/starlink-traffic-growth-2024.jpg`,
    x: 2.95, y: 1.15, w: 6.7, h: 4.15,
    sizing: { type: "contain", w: 6.7, h: 4.15 }
  });
}

// ═══════════════════════════════════════════════════════════════════════════
// SLIDE 3 — Google Leads Top 10 Services as Generative AI Rises
// ═══════════════════════════════════════════════════════════════════════════
{
  const slide = pres.addSlide();
  slide.background = { color: C.navy };
  addHeader(slide,
    "Google Leads Top 10 Services as Generative AI Rises",
    "Rankings based on aggregate data from Cloudflare's 1.1.1.1 DNS resolver · Google tops ranking for second consecutive year"
  );

  // Left — top 10 table
  const tableRows = [
    [
      { text: "RANK", options: { bold: true, color: C.orange, fill: { color: C.navyMid }, fontSize: 10 } },
      { text: "SERVICE", options: { bold: true, color: C.orange, fill: { color: C.navyMid }, fontSize: 10 } },
    ],
    ...([
      ["#1", "Google"],
      ["#2", "Facebook"],
      ["#3", "Apple"],
      ["#4", "TikTok"],
      ["#5", "AWS"],
      ["#6", "Microsoft"],
      ["#7", "Instagram"],
      ["#8", "YouTube"],
      ["#9", "Amazon"],
      ["#10", "WhatsApp"],
    ].map(([rank, svc], i) => [
      { text: rank, options: { color: i === 0 ? C.orange : C.white, bold: i === 0, fill: { color: i % 2 === 0 ? C.navyMid : C.navy }, fontSize: 11 } },
      { text: svc, options: { color: C.white, fill: { color: i % 2 === 0 ? C.navyMid : C.navy }, fontSize: 11 } },
    ]))
  ];

  slide.addTable(tableRows, {
    x: 0.35, y: 1.12, w: 3.4, h: 4.2,
    colW: [1.0, 2.4],
    border: { pt: 0.5, color: C.navyLight },
    autoPage: false
  });

  // Right — image
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 3.95, y: 1.1, w: 5.75, h: 3.5,
    fill: { color: C.navyMid }, line: { color: C.navyLight }
  });
  slide.addImage({
    path: `${ASSETS}/top-10-internet-services.jpg`,
    x: 4.0, y: 1.15, w: 5.65, h: 3.4,
    sizing: { type: "contain", w: 5.65, h: 3.4 }
  });

  // Generative AI callout box
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 3.95, y: 4.72, w: 5.75, h: 0.75,
    fill: { color: C.navyMid }, line: { color: C.orange }
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 3.95, y: 4.72, w: 0.06, h: 0.75,
    fill: { color: C.orange }, line: { color: C.orange }
  });
  slide.addText([
    { text: "Generative AI ", options: { bold: true, color: C.orange } },
    { text: "continued its rapid rise throughout 2024 — while the Metaverse receded from relevance.", options: { color: C.ice } }
  ], {
    x: 4.1, y: 4.72, w: 5.5, h: 0.75,
    fontSize: 10.5, fontFace: "Calibri", valign: "middle", margin: 0
  });
}

// ═══════════════════════════════════════════════════════════════════════════
// SLIDE 4 — Post-Quantum Encryption Jumps from 2% to 13% of TLS 1.3
// ═══════════════════════════════════════════════════════════════════════════
{
  const slide = pres.addSlide();
  slide.background = { color: C.navy };
  addHeader(slide,
    "Post-Quantum Encryption Jumps from 2% to 13% of TLS 1.3",
    "Technology adoption shifts reshaping security, protocol usage, and developer preferences across the Internet"
  );

  // Three stat cards top-right
  const cards = [
    { v: "2% → 13%", l: "Post-quantum TLS 1.3 adoption after Chrome 124 (Apr 17)", c: C.teal },
    { v: "21%", l: "HTTP/3 adoption — faster, encrypted by default over QUIC", c: C.orange },
    { v: "~12%", l: "Go leads API client languages — most popular for automated requests", c: C.green },
  ];
  cards.forEach((card, i) => {
    addStatCard(slide, 5.5 + (i === 0 ? 0 : 0), 1.1 + i * 1.46, 4.15, 1.28, card.v, card.l, card.c);
  });

  // Post-quantum image left
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.35, y: 1.1, w: 4.95, h: 4.25,
    fill: { color: C.navyMid }, line: { color: C.navyLight }
  });
  slide.addImage({
    path: `${ASSETS}/post-quantum-encryption-adoption.jpg`,
    x: 0.4, y: 1.15, w: 4.85, h: 4.15,
    sizing: { type: "contain", w: 4.85, h: 4.15 }
  });

  // Additional tech stats below the cards
  const techRows = [
    ["Metric", "Value"],
    ["iOS traffic share", "33%"],
    ["Google search referrals", "89%"],
    ["IPv6 dual-stack adoption", "28%"],
  ];
  const styledRows = techRows.map((row, ri) => row.map(cell => ({
    text: cell,
    options: {
      bold: ri === 0,
      color: ri === 0 ? C.orange : C.white,
      fill: { color: ri === 0 ? C.navyMid : (ri % 2 === 0 ? C.navyLight : C.navy) },
      fontSize: 9.5
    }
  })));
  slide.addTable(styledRows, {
    x: 5.5, y: 5.44, w: 4.15, h: 0.9,
    colW: [2.6, 1.55],
    border: { pt: 0.5, color: C.navyLight }
  });
}

// ═══════════════════════════════════════════════════════════════════════════
// SLIDE 5 — 225 Major Disruptions: Government Shutdowns Lead Outage Causes
// ═══════════════════════════════════════════════════════════════════════════
{
  const slide = pres.addSlide();
  slide.background = { color: C.navy };
  addHeader(slide,
    "225 Major Disruptions: Government Shutdowns Lead Outage Causes",
    "Cloudflare Radar Outage Center tracked 225 major Internet disruptions globally in 2024 — scope and duration measured via Cloudflare traffic data"
  );

  // Left — breakdown table
  const disruptionData = [
    ["CAUSE", "COUNT"],
    ["Government Directed", "116+"],
    ["Cable Cut", "41"],
    ["Unknown", "16"],
    ["Power Outage", "16"],
    ["Technical Problem", "9"],
    ["Military Action", "9"],
    ["Weather", "8"],
    ["Maintenance", "4"],
    ["Cyber Attack", "4"],
    ["Natural Disaster", "1"],
    ["Fire", "1"],
  ];
  const disruptionRows = disruptionData.map((row, ri) => {
    const isHeader = ri === 0;
    const isTop = ri === 1; // Government directed — highlight
    return row.map((cell, ci) => ({
      text: cell,
      options: {
