    });
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 4.05, y: iy, w: 0.05, h: 0.5,
      fill: { color: i === 0 ? C.red : C.yellow }, line: { color: i === 0 ? C.red : C.yellow }
    });
    slide.addText(ins.text, {
      x: 4.18, y: iy, w: 5.38, h: 0.5,
      fontSize: 9, color: C.ice, fontFace: "Calibri", valign: "middle", wrap: true, margin: 0
    });
  });
}

// ═══════════════════════════════════════════════════════════════════════════
// SLIDE 6 — 6.5% of Traffic Mitigated: Persistent Threats and Bot Concentration
// ═══════════════════════════════════════════════════════════════════════════
{
  const slide = pres.addSlide();
  slide.background = { color: C.navy };
  addHeader(slide,
    "6.5% of Traffic Mitigated: Persistent Threats and Bot Concentration",
    "Security findings from Cloudflare's global network — DDoS, bot traffic, email threats, and vulnerability exploitation in 2024"
  );

  // 2x2 grid of security stat cards
  const secCards = [
    { v: "6.5%", l: "Of all traffic processed was mitigated — indicating pervasive, ongoing threats at scale", c: C.red, x: 0.35, y: 1.12 },
    { v: "68%", l: "Of global bot traffic originated from just the top 10 countries — highly concentrated sources", c: C.yellow, x: 5.2, y: 1.12 },
    { v: "4.3%", l: "Of processed emails were malicious; 43% of those contained deceptive links to trick recipients", c: C.orange, x: 0.35, y: 2.65 },
    { v: "Log4j", l: "CVE-2021-44228 from Dec 2021 is still actively exploited 3+ years later — persistence of known vulns", c: C.teal, x: 5.2, y: 2.65 },
  ];
  secCards.forEach(card => {
    addStatCard(slide, card.x, card.y, 4.55, 1.28, card.v, card.l, card.c);
  });

  // Most attacked sector highlight
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.35, y: 4.05, w: 9.4, h: 1.3,
    fill: { color: C.navyMid }, line: { color: C.red }
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.35, y: 4.05, w: 0.06, h: 1.3,
    fill: { color: C.red }, line: { color: C.red }
  });
  slide.addText("MOST ATTACKED SECTOR", {
    x: 0.55, y: 4.1, w: 4, h: 0.35,
    fontSize: 9, bold: true, color: C.red, fontFace: "Calibri",
    charSpacing: 2, margin: 0
  });
  slide.addText("Gambling & Games", {
    x: 0.55, y: 4.42, w: 5, h: 0.55,
    fontSize: 22, bold: true, color: C.white, fontFace: "Calibri", margin: 0
  });
  // Additional metric
  slide.addText([
    { text: "RPKI Valid Routes: ", options: { bold: true, color: C.orange } },
    { text: "+6.4% increase in 2024 — improving Internet routing security.", options: { color: C.ice } },
    { text: "   |   ", options: { color: C.muted } },
    { text: ".bar TLD: ", options: { bold: true, color: C.orange } },
    { text: "Largest source of malicious and spam email observed.", options: { color: C.ice } },
  ], {
    x: 0.55, y: 5.0, w: 9.1, h: 0.3,
    fontSize: 9.5, fontFace: "Calibri", margin: 0
  });
}

// ═══════════════════════════════════════════════════════════════════════════
// SLIDE 7 — Five Takeaways Shaping the 2025 Internet Outlook
// ═══════════════════════════════════════════════════════════════════════════
{
  const slide = pres.addSlide();
  slide.background = { color: C.navy };

  // Top accent
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.06,
    fill: { color: C.orange }, line: { color: C.orange }
  });

  slide.addText("Five Takeaways Shaping the 2025 Internet Outlook", {
    x: 0.45, y: 0.18, w: 9.1, h: 0.52,
    fontSize: 22, bold: true, color: C.white, fontFace: "Calibri", margin: 0
  });
  slide.addText("Strategic findings from Cloudflare Radar 2024 to inform planning for network and security leaders", {
    x: 0.45, y: 0.68, w: 9.1, h: 0.3,
    fontSize: 11, color: C.ice, fontFace: "Calibri", margin: 0
  });

  const takeaways = [
    {
      num: "01",
      title: "Traffic Growth is Structural",
      body: "17% YoY growth with Starlink's 3.3x surge reflects durable demand — plan capacity and CDN strategy for accelerating baselines, especially in emerging and satellite-connected markets.",
      color: C.orange
    },
    {
      num: "02",
      title: "Post-Quantum Encryption is Now",
      body: "The 2%→13% TLS 1.3 jump driven by Chrome 124 shows browser vendors can reshape cryptographic baselines overnight. Evaluate quantum-resistant readiness across your entire TLS infrastructure.",
      color: C.teal
    },
    {
      num: "03",
      title: "Connectivity is a Geopolitical Variable",
      body: "Government-directed shutdowns caused 116+ of 225 disruptions in 2024 — more than all other causes combined. Multi-path routing and resilience planning are essential for global operations.",
      color: C.red
    },
    {
      num: "04",
      title: "Known Vulnerabilities Remain Live Threats",
      body: "Log4j (2021) is still being actively exploited. 6.5% traffic mitigation and Gambling/Games as top target sector underscore the need for continuous patching and DDoS-resilient architectures.",
      color: C.yellow
    },
    {
      num: "05",
      title: "Developer Ecosystem is Shifting",
      body: "Go leading API client languages at ~12% reflects a shift toward performance-first, compiled languages in backend automation. Factor this into API gateway and observability tooling investments.",
      color: C.green
    },
  ];

  takeaways.forEach((t, i) => {
    const row = Math.floor(i / 3);
    const col = i % 3;
    const colCount = i < 3 ? 3 : 2;
    const cardW = i < 3 ? 3.1 : 4.65;
    const startX = i < 3 ? 0.35 : 0.35 + (i - 3) * (4.65 + 0.2);
    const cx = i < 3 ? 0.35 + col * 3.18 : startX;
    const cy = 1.12 + row * 2.22;

    slide.addShape(pres.shapes.RECTANGLE, {
      x: cx, y: cy, w: cardW, h: 2.0,
      fill: { color: C.navyMid },
      shadow: { type: "outer", color: "000000", blur: 8, offset: 3, angle: 135, opacity: 0.25 }
    });
    slide.addShape(pres.shapes.RECTANGLE, {
      x: cx, y: cy, w: cardW, h: 0.06,
      fill: { color: t.color }, line: { color: t.color }
    });
    // Number
    slide.addText(t.num, {
      x: cx + 0.15, y: cy + 0.12, w: 0.6, h: 0.45,
      fontSize: 20, bold: true, color: t.color, fontFace: "Calibri", margin: 0
    });
    // Title
    slide.addText(t.title, {
      x: cx + 0.78, y: cy + 0.12, w: cardW - 0.93, h: 0.45,
      fontSize: 11, bold: true, color: C.white, fontFace: "Calibri",
      valign: "top", margin: 0
    });
    // Body
    slide.addText(t.body, {
      x: cx + 0.15, y: cy + 0.65, w: cardW - 0.3, h: 1.28,
      fontSize: 9, color: C.ice, fontFace: "Calibri",
      valign: "top", wrap: true, margin: 0
    });
  });

  // Footer
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 5.38, w: 10, h: 0.245,
    fill: { color: C.navyMid }, line: { color: C.navyMid }
  });
  slide.addText("radar.cloudflare.com/year-in-review/2024  ·  Data from Cloudflare's global network  ·  © 2025 Cloudflare, Inc.", {
    x: 0.35, y: 5.38, w: 9.3, h: 0.245,
    fontSize: 8, color: C.muted, fontFace: "Calibri", valign: "middle", margin: 0
  });
}

// ── Write file ────────────────────────────────────────────────────────────
pres.writeFile({ fileName: "/app/output/final_deck.pptx" })
  .then(() => console.log("✅  Saved: /app/output/final_deck.pptx"))
  .catch(err => { console.error("❌  Error:", err); process.exit(1); });

